local BookCoverGaugeMaker = {}
local PRODUCTS = {
    iron_bookcovergauge = { name = "Železni merilec za naslovnice", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni merilec za naslovnice za knjigoveze." },
    bronze_bookcovergauge = { name = "Bronast merilec za naslovnice", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast merilec za naslovnice za knjigoveze." },
    silver_bookcovergauge = { name = "Srebrn merilec za naslovnice", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn merilec za naslovnice za knjigoveze." },
    gilded_bookcovergauge = { name = "Pozlačen merilec za naslovnice", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen merilec za naslovnice za knjigoveze." },
    jewel_set_bookcovergauge = { name = "Draguljast merilec za naslovnice", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast merilec za naslovnice za knjigoveze." },
    royal_sovereign_bookcovergauge = { name = "Kraljevski suveren merilec za naslovnice", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren merilec za naslovnice z biseri za krono." },
}
local BUILDINGS = {
    bookcovergauge_workshop = { name = "Bookcovergauge delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    bookcovergauge_house = { name = "Bookcovergauge hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_bookcovergauge_atelier = { name = "Mojstrski bookcovergauge atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_bookcovergauge_palace = { name = "Suverena bookcovergauge palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
BookCoverGaugeMaker.ironStock=14; BookCoverGaugeMaker.bronzeStock=12; BookCoverGaugeMaker.woodStock=14; BookCoverGaugeMaker.leatherStock=8; BookCoverGaugeMaker.silverStock=8; BookCoverGaugeMaker.goldStock=6; BookCoverGaugeMaker.jewelStock=4; BookCoverGaugeMaker.pearlStock=4
BookCoverGaugeMaker.productStock = {}; BookCoverGaugeMaker.buildings = {}; BookCoverGaugeMaker.maker = nil; BookCoverGaugeMaker.activeMaking = {}; BookCoverGaugeMaker.totalProducts = 0; BookCoverGaugeMaker.dayTimer = 0
function BookCoverGaugeMaker.init() BookCoverGaugeMaker.ironStock=14; BookCoverGaugeMaker.bronzeStock=12; BookCoverGaugeMaker.woodStock=14; BookCoverGaugeMaker.leatherStock=8; BookCoverGaugeMaker.silverStock=8; BookCoverGaugeMaker.goldStock=6; BookCoverGaugeMaker.jewelStock=4; BookCoverGaugeMaker.pearlStock=4; BookCoverGaugeMaker.productStock={}; BookCoverGaugeMaker.buildings={}; BookCoverGaugeMaker.maker=nil; BookCoverGaugeMaker.activeMaking={}; BookCoverGaugeMaker.totalProducts=0; BookCoverGaugeMaker.dayTimer=0; print("[BookCoverGaugeMaker] Royal Book Cover Gauge Maker System initialized (6 products, 4 buildings)") end
function BookCoverGaugeMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BookCoverGaugeMaker.maker={name=n or ("Merilnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Merilnik najet: %s (spretnost: %d)",BookCoverGaugeMaker.maker.name,s),"success") end; return true end
function BookCoverGaugeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BookCoverGaugeMaker.build(id) local ok,e=BookCoverGaugeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BookCoverGaugeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BookCoverGaugeMaker.getQualityBonus() local b=0; for _,bd in ipairs(BookCoverGaugeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BookCoverGaugeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BookCoverGaugeMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BookCoverGaugeMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BookCoverGaugeMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BookCoverGaugeMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BookCoverGaugeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BookCoverGaugeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BookCoverGaugeMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BookCoverGaugeMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BookCoverGaugeMaker.buildings==0 then return false,"Potrebna merilna delavnica" end; if not BookCoverGaugeMaker.maker then return false,"Potreben merilnik" end; return true end
function BookCoverGaugeMaker.make(pt,qty) qty=qty or 1; local ok,e=BookCoverGaugeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BookCoverGaugeMaker.ironStock=BookCoverGaugeMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BookCoverGaugeMaker.bronzeStock=BookCoverGaugeMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BookCoverGaugeMaker.woodStock=BookCoverGaugeMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BookCoverGaugeMaker.leatherStock=BookCoverGaugeMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BookCoverGaugeMaker.silverStock=BookCoverGaugeMaker.silverStock-d.silverCost*qty end; if d.goldCost then BookCoverGaugeMaker.goldStock=BookCoverGaugeMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BookCoverGaugeMaker.jewelStock=BookCoverGaugeMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BookCoverGaugeMaker.pearlStock=BookCoverGaugeMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BookCoverGaugeMaker.maker then t=math.max(1,t-math.floor(BookCoverGaugeMaker.maker.skill/13)) end; table.insert(BookCoverGaugeMaker.activeMaking,{id="bookcovergauge_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BookCoverGaugeMaker.completeMaking(m) local q=1.0+(BookCoverGaugeMaker.getQualityBonus()/100); if BookCoverGaugeMaker.maker then q=q+(BookCoverGaugeMaker.maker.skill/140) end; q=math.min(2.5,q); BookCoverGaugeMaker.productStock[m.productType]=(BookCoverGaugeMaker.productStock[m.productType] or 0)+m.quantity; BookCoverGaugeMaker.totalProducts=BookCoverGaugeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookCoverGaugeMaker.maker then BookCoverGaugeMaker.maker.itemsMade=BookCoverGaugeMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookCoverGaugeMaker.maker.skill=math.min(100,BookCoverGaugeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Merilec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bookcovergauge.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BookCoverGaugeMaker.update(dt) if not _G.state then return end; BookCoverGaugeMaker.dayTimer=BookCoverGaugeMaker.dayTimer+dt; if BookCoverGaugeMaker.dayTimer>=30 then BookCoverGaugeMaker.dayTimer=0; for i=#BookCoverGaugeMaker.activeMaking,1,-1 do local m=BookCoverGaugeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BookCoverGaugeMaker.completeMaking(m); table.remove(BookCoverGaugeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BookCoverGaugeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BookCoverGaugeMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BookCoverGaugeMaker.getStats() return {ironStock=BookCoverGaugeMaker.ironStock,bronzeStock=BookCoverGaugeMaker.bronzeStock,woodStock=BookCoverGaugeMaker.woodStock,leatherStock=BookCoverGaugeMaker.leatherStock,silverStock=BookCoverGaugeMaker.silverStock,goldStock=BookCoverGaugeMaker.goldStock,jewelStock=BookCoverGaugeMaker.jewelStock,pearlStock=BookCoverGaugeMaker.pearlStock,productStock=BookCoverGaugeMaker.productStock,numBuildings=#BookCoverGaugeMaker.buildings,hasMaker=BookCoverGaugeMaker.maker~=nil,makerName=BookCoverGaugeMaker.maker and BookCoverGaugeMaker.maker.name or "—",makerSkill=BookCoverGaugeMaker.maker and BookCoverGaugeMaker.maker.skill or 0,activeMaking=#BookCoverGaugeMaker.activeMaking,totalProducts=BookCoverGaugeMaker.totalProducts} end
return BookCoverGaugeMaker
